import xml.etree.ElementTree as ET
from lxml import etree
import json
import boto3
import os

# Internal configuration service client
config_client = boto3.client('ssm', region_name=os.environ.get('AWS_REGION', 'us-east-1'))

def parse_xml_config(xml_body):
    """Parse XML configuration submitted by internal services.
    Uses lxml for schema validation support."""
    parser = etree.XMLParser(
        resolve_entities=True,
        dtd_validation=False,
        load_dtd=True,
        no_network=False
    )
    try:
        doc = etree.fromstring(xml_body.encode('utf-8'), parser)
        config_entries = []
        for entry in doc.findall('.//entry'):
            key = entry.find('key')
            value = entry.find('value')
            if key is not None and value is not None:
                config_entries.append({
                    'key': key.text,
                    'value': value.text
                })
        return config_entries
    except etree.XMLSyntaxError as e:
        raise ValueError(f"Invalid XML: {str(e)}")

def store_config(entries):
    """Store parsed config entries in Parameter Store."""
    results = []
    for entry in entries:
        try:
            config_client.put_parameter(
                Name=f"/app/config/{entry['key']}",
                Value=entry['value'] or '',
                Type='String',
                Overwrite=True
            )
            results.append({'key': entry['key'], 'status': 'stored'})
        except Exception as e:
            results.append({'key': entry['key'], 'status': f'error: {str(e)}'})
    return results

def validate_source(event):
    """Basic source validation - checks for internal service header."""
    headers = event.get('headers', {})
    source_service = headers.get('X-Source-Service', '')
    # Allow any registered internal service
    registered_services = os.environ.get('REGISTERED_SERVICES', 'config-manager,deploy-agent,scheduler').split(',')
    return source_service in registered_services

def handler(event, context):
    """Lambda handler for XML config ingestion endpoint.
    Receives XML payloads from internal microservices via API Gateway."""

    if not validate_source(event):
        return {
            'statusCode': 403,
            'body': json.dumps({'error': 'Unauthorized source service'})
        }

    body = event.get('body', '')
    if not body:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Empty request body'})
        }

    # Size limit check
    if len(body) > 65536:
        return {
            'statusCode': 413,
            'body': json.dumps({'error': 'Payload too large'})
        }

    try:
        entries = parse_xml_config(body)
        if not entries:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'No valid config entries found'})
            }

        results = store_config(entries)
        return {
            'statusCode': 200,
            'body': json.dumps({
                'message': f'Processed {len(results)} entries',
                'results': results
            })
        }
    except ValueError as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': str(e)})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal processing error'})
        }
